// Transforms `a` so every element becomes 3, then accumulates the total into `sum[0]`.
// Preconditions (as described):
// - 0 < N < 1000
// - a.len() == N as usize
// - sum.len() == 1
pub fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, n: i32) {
    debug_assert!(n > 0 && n < 1000, "N must be in (0, 1000)");
    debug_assert!(a.len() == n as usize, "a.len() must equal N");
    debug_assert!(sum.len() == 1, "sum must have length exactly 1");

    // Keep lengths unchanged; mutate values in-place.
    for x in a.iter_mut() {
        *x = 3;
    }

    // Accumulate sum of the array into the single-element output buffer.
    let mut total: i32 = 0;
    for &x in a.iter() {
        total += x;
    }
    sum[0] = total;

    // Given the transformation, total == 3 * a.len() == 3 * N.
    debug_assert!(sum[0] == 3 * n);
}